export interface RouterConfigItem {
  //This the path that shows up in the browser url
  path: string;

  //This will normally be remoteEntry.js
  url: string;

  //Syncs up with ModuleFederation 'name'
  remote: string;

  //Syncs up with ModuleFederation 'exposes'
  module: string;

  //The context object will passed into the mfe when it is initialized.
  context: {
    [key: string]: any
  };

  //Tells whether the route will be inserted in the header or the main content area.
  injectionLocation?: 'application-shell:content-main' | 'application-shell:content-header';

  //Sets the layout for the MFE. Defaults to no layout and places content directly into the injectionLocation
  layout?: 'standard' | 'no-footer';

  landingPages?: Array<string>;
}
